  var title=page.querySelector(':scope > .page-header .page-title');if(title)title.textContent='Incident Management';
  var subtitle=document.getElementById('ev-subtitle');if(subtitle)subtitle.textContent='Report - Triage - Investigate - Correct - Learn';
  var legacyHeaderActions=page.querySelector(':scope > .page-header > div:last-child');if(legacyHeaderActions)legacyHeaderActions.style.display='none';
  var legacyMetrics=page.querySelector(':scope > .module-metrics');if(legacyMetrics)legacyMetrics.style.display='none';
  var tabbar=page.querySelector(':scope > .module-tabs');if(tabbar&&!tabbar.dataset.imx){tabbar.dataset.imx='1';tabbar.innerHTML=TOP_TABS.map(function(t){return '<button class="mtg-tab '+(t[0]==='dashboard'?'active':'')+'" id="ims-tab-'+t[0]+'" data-auris-module-onclick="b0017" data-auris-module-args="'+encodeURIComponent(JSON.stringify([t[0]]))+'" style="white-space:nowrap"><span class="imx-tab-icon"><i class="ti '+TAB_ICONS[t[0]]+'"></i></span>'+esc(t[1])+'</button>';}).join('');}
  CUSTOM_TABS.forEach(function(tab){if(!document.getElementById('ims-view-'+tab)){var view=document.createElement('div');view.id='ims-view-'+tab;view.className='imx-view';tabbar.parentNode.insertBefore(view,tabbar.nextSibling);}});
  var actionTitle=page.querySelector('#ims-view-actions > .card:first-child div:first-child');if(actionTitle)actionTitle.innerHTML='<i class="ti ti-list-check"></i> Action Register';
  if(!document.getElementById('imx-drawer')){var drawer=document.createElement('div');drawer.id='imx-drawer';drawer.className='imx-drawer-bg';drawer.innerHTML='<aside class="imx-drawer"><div class="imx-drawer-head"><div><span>Governed incident record</span><h2 id="imx-drawer-title">Incident record</h2></div><button type="button" class="imx-btn" data-auris-module-onclick="b0018"><i class="ti ti-x"></i></button></div><div class="imx-drawer-body" id="imx-drawer-body"></div><div class="imx-drawer-foot" id="imx-drawer-foot"></div></aside>';drawer.onclick=function(e){if(e.target===drawer)window.imv2CloseDrawer();};document.body.appendChild(drawer);}
  enhanceReportForm();enhanceInvestigationTabs();return true;
