  var banner=view.querySelector('.card');if(!banner)return;
  var block=document.createElement('div');block.id='imx-emergency-card';block.className='imx-emergency';block.innerHTML='<h3><i class="ti ti-alert-triangle"></i> Emergency and reporting gate</h3><p>Do not delay emergency help, medical care, spill response, fire response or site isolation to complete this form.</p><div class="imx-emergency-grid">'+field('Immediate danger','imx-immediate-danger','select',[['false','No'],['true','Yes']],false)+field('Emergency help needed','imx-emergency-gate','select',[['none','No emergency help'],['medical','Medical help'],['fire','Fire / rescue'],['spill','Spill response'],['security','Security / police']], 'none')+field('Event time estimated','imx-estimated-time','select',[['false','Exact / confirmed'],['true','Estimated']],false)+field('Reporter mode','imx-reporter-mode','select',[['named','Named'],['confidential','Confidential'],['anonymous','Anonymous where policy permits']],'named')+field('Confidentiality','imx-confidentiality','select',[['internal','Internal'],['restricted','Restricted case team'],['privileged','Legal / privileged']],'internal')+field('Likelihood','imx-likelihood','select',[['rare','Rare'],['unlikely','Unlikely'],['possible','Possible'],['likely','Likely'],['almost_certain','Almost certain']],'possible')+field('Work activity','imx-work-activity','text',null,'','full')+'</div><div class="imx-banner privacy" style="margin:10px 0 0">Anonymous and confidential reporting follows the published company policy. Technical and legal limits must be explained to the reporter.</div>';
  banner.insertAdjacentElement('afterend',block);
