  var top=document.getElementById('ims-save-top');if(top&&!document.getElementById('imx-draft-top'))top.insertAdjacentHTML('beforebegin','<button type="button" id="imx-draft-top" class="btn" style="background:#fff;color:#7F1D1D;font-weight:700" data-auris-module-onclick="b0019"><i class="ti ti-device-floppy"></i>Save draft</button>');
  var bottom=document.getElementById('ims-save-bottom');if(bottom&&!document.getElementById('imx-draft-bottom'))bottom.insertAdjacentHTML('beforebegin','<button type="button" id="imx-draft-bottom" class="btn" data-auris-module-onclick="b0019"><i class="ti ti-device-floppy"></i>Save draft</button>');
