async function query(path){return await api(path);}
async function loadAll(force){
  if(X.loading||(!force&&X.loaded))return;X.loading=true;X.schemaReady=true;
  var c=companyId();if(!c){X.loading=false;X.loaded=true;render();return;}
  var requests=[['events','/events?select=*&company_id=eq.'+encodeURIComponent(c)+'&order=event_date.desc,created_at.desc&limit=1000'],['investigations','/investigations?select=*&company_id=eq.'+encodeURIComponent(c)+'&order=created_at.desc&limit=500'],['evidence','/incident_evidence?select=*&company_id=eq.'+encodeURIComponent(c)+'&order=created_at.desc&limit=500'],['actions','/action_tracker?select=*&company_id=eq.'+encodeURIComponent(c)+'&order=created_at.desc&limit=500'],['records','/'+RECORD_TABLE+'?select=*&company_id=eq.'+encodeURIComponent(c)+'&order=created_at.desc&limit=1000'],['config','/'+CONFIG_TABLE+'?select=*&company_id=eq.'+encodeURIComponent(c)+'&order=created_at.desc&limit=500'],['audit','/'+AUDIT_TABLE+'?select=*&company_id=eq.'+encodeURIComponent(c)+'&order=created_at.desc&limit=500']];
  await Promise.all(requests.map(async function(item){try{X.data[item[0]]=await query(item[1])||[];}catch(e){X.data[item[0]]=[];if(['records','config','audit'].includes(item[0]))X.schemaReady=false;}}));
  if(typeof imsAllData!=='undefined')imsAllData=X.data.events;if(typeof imsInvAllData!=='undefined')imsInvAllData=X.data.investigations;
  X.loaded=true;X.loading=false;render();
}

function render(){ensureShell();var view=document.getElementById('ims-view-'+X.tab);if(!view||!CUSTOM_TABS.includes(X.tab))return;if(X.loading){view.innerHTML=empty('Loading authorised incident records','Applying company, case, privacy and role permissions.');return;}var map={dashboard:dashboardView,mywork:myWorkView,triage:triageView,regulatory:regulatoryView,lessons:lessonsView,reports:reportsView,configuration:configurationView};view.innerHTML=(!X.schemaReady?'<div class="imx-banner warn"><strong>Database upgrade required.</strong> Apply <code>incident_management_module_upgrade.sql</code>. Existing incident reporting remains available while governed workspaces wait for the schema.</div>':'')+map[X.tab]();}

window.imv2SwitchTab=function(tab,btn){ensureShell();if(!TOP_TABS.some(function(t){return t[0]===tab;}))tab='investigate';X.tab=tab;document.querySelectorAll('#page-events > .module-tabs .mtg-tab').forEach(function(b){b.classList.remove('active');});var selected=btn||document.getElementById('ims-tab-'+tab);if(selected)selected.classList.add('active');document.querySelectorAll('#page-events > [id^="ims-view-"]').forEach(function(v){v.style.display='none';v.classList.remove('active');});var view=document.getElementById('ims-view-'+tab);if(view){view.style.display='block';view.classList.add('active');}if(tab==='report'){if(typeof imsSetFormMode==='function')imsSetFormMode(true);if(typeof imsNewIncident==='function'&&!imsEditId)imsNewIncident();return;}if(typeof imsSetFormMode==='function')imsSetFormMode(false);if(CUSTOM_TABS.includes(tab)){render();return;}if(tab==='register'&&typeof imsLoadRegister==='function')imsLoadRegister();else if(tab==='investigate'&&typeof imsLoadInvestigations==='function')imsLoadInvestigations();else if(tab==='actions'&&typeof imsLoadCAList==='function')imsLoadCAList();};

window.loadIncidentManagementV2=function(){if(!ensureShell())return;X.tab='dashboard';window.imv2SwitchTab('dashboard',document.getElementById('ims-tab-dashboard'));loadAll(true);};
