function dashboardView(){
  var events=X.data.events||[],invs=X.data.investigations||[],actions=X.data.actions||[],regs=recordRows('regulatory'),now=new Date(),open=events.filter(function(x){return !['closed','cancelled','archived'].includes(x.status);}),triage=events.filter(function(x){return ['submitted','awaiting_triage','triage'].includes(x.status)||!recordForIncident('triage',x.id).length;}),hipo=events.filter(function(x){return ['critical','high'].includes(String(x.potential_severity||x.severity||'').toLowerCase());}),invOver=invs.filter(function(x){return x.target_date&&new Date(x.target_date)<now&&!['closed','completed'].includes(x.status);}),actionOver=actions.filter(function(x){var due=x.target_date||x.due_date;return due&&new Date(due)<now&&!['closed','completed','effective_closed'].includes(x.status);}),regDue=regs.filter(function(x){return x.due_date&&new Date(x.due_date)<now&&!['submitted','acknowledged','closed'].includes(x.status);}),closed=events.filter(function(x){return x.status==='closed';});
  var months=[],counts=[];for(var i=11;i>=0;i--){var d=new Date(now.getFullYear(),now.getMonth()-i,1),key=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');months.push(d.toLocaleString('en-GB',{month:'short'}));counts.push(events.filter(function(x){return String(x.event_date||x.created_at||'').slice(0,7)===key;}).length);}var max=Math.max(1,Math.max.apply(null,counts));
  var urgent=open.slice().sort(function(a,b){return ({critical:4,high:3,medium:2,low:1}[String(b.potential_severity||b.severity).toLowerCase()]||0)-({critical:4,high:3,medium:2,low:1}[String(a.potential_severity||a.severity).toLowerCase()]||0);}).slice(0,6);
  return head('Incident Dashboard','Authorised operational metrics reconcile to the same incident records used by each drill-down.',button('Export','imv2OpenReportForm()','','ti-download')+button('Report incident','imv2NewIncident()','primary','ti-plus'))+'<div class="imx-grid six">'+metric('ti-alert-triangle','Open incidents',open.length,'Active authorised cases','red','register')+metric('ti-inbox','Awaiting triage',triage.length,'Submitted or incomplete','amber','triage')+metric('ti-shield-exclamation','Critical / HiPo',hipo.length,'Potential and actual kept separate','red','triage')+metric('ti-search','Investigations overdue',invOver.length,'Against current plan target','amber','investigate')+metric('ti-list-check','Actions overdue',actionOver.length,'Completion is not verification','amber','actions')+metric('ti-scale','Regulatory deadlines',regDue.length,'Human decision remains required','blue','regulatory')+'</div><div class="imx-grid two" style="margin-top:12px"><section class="imx-card"><div class="imx-card-title">Incident trend <span>'+events.length+' records</span></div><div class="imx-card-sub">Monthly incident count. No missing denominator is converted to zero-rate performance.</div><div class="imx-trend">'+counts.map(function(c,i){return '<span style="height:'+Math.max(3,Math.round(c/max*110))+'px" title="'+c+' incident(s)"><b>'+months[i]+'</b></span>';}).join('')+'</div></section><section class="imx-card"><div class="imx-card-title">Investigation attention</div><div class="imx-card-sub">Highest potential or overdue cases first.</div>'+(urgent.length?'<div class="imx-list">'+urgent.map(function(x){return '<div class="imx-row"><div><b>'+esc(incidentRef(x))+' · '+esc(incidentTitle(x).slice(0,65))+'</b><small>'+esc(x.location||'-')+' · '+fmtDate(x.event_date)+'</small></div>'+badge(x.potential_severity||x.severity||x.status)+'</div>';}).join('')+'</div>':empty('No open incident attention items','Authorised cases will appear here when reported.'))+'</section></div><div class="imx-grid three" style="margin-top:12px">'+metric('ti-circle-check','Cases closed',closed.length,'Immutable closure snapshot required','','register')+metric('ti-search','Active investigations',invs.filter(function(x){return !['closed','completed'].includes(x.status);}).length,'Open the selected case to view its child records','blue','investigate')+metric('ti-bulb','Published lessons',recordRows('lesson').filter(function(x){return x.status==='published';}).length,'Anonymised and approved','','lessons')+'</div>';
}

