  var me=userName().toLowerCase(),mine=function(x){return !x.owner_name&&!x.assigned_to_name&&!x.assigned_to||[x.owner_name,x.assigned_to_name,x.assigned_to,x.investigator,x.reported_by].some(function(v){return String(v||'').toLowerCase()===me;});},events=(X.data.events||[]).filter(mine).filter(function(x){return !['closed','cancelled','archived'].includes(x.status);}),invs=(X.data.investigations||[]).filter(mine).filter(function(x){return !['closed','completed'].includes(x.status);}),records=(X.data.records||[]).filter(mine).filter(function(x){return !['closed','published','archived','effective_closed'].includes(x.status);}),actions=(X.data.actions||[]).filter(mine).filter(function(x){return !['closed','completed','effective_closed'].includes(x.status);});
