function fieldHtml(def,row){var name=def[0],key=def[1],type=def[2],options=def[3],cls=def[4],value=row[key];if(value==null&&row.payload)value=row.payload[key];if(type==='incident'){options=[['','Select incident']].concat((X.data.events||[]).map(function(x){return [x.id,incidentRef(x)+' · '+incidentTitle(x).slice(0,62)];}));type='select';}else if(type==='investigation'){options=[['','Select investigation']].concat((X.data.investigations||[]).map(function(x){return [x.id,(x.investigation_ref||'INV-DRAFT')+' · '+(x.description||x.incident_description||'Investigation').slice(0,55)];}));type='select';}if(['payload','test_cases'].includes(key)&&typeof value==='object')value=JSON.stringify(value,null,2);if(key==='source_links'&&Array.isArray(row.source_links))value=row.source_links.join(', ');return field(name,'imx-f-'+key,type,options,value,cls);}
