window.imv2CloseDrawer=function(force){if(X.drawerDirty&&!force&&!confirm('Discard unsaved changes?'))return;document.getElementById('imx-drawer')?.classList.remove('open');};
window.imv2OpenForm=function(kind,row){var form=FORMS[kind];if(!form)return;row=row||{};if(kind==='config'&&!row.workspace)row.workspace=X.configGroup;var body='<div class="imx-banner">Save Draft preserves work. Submit, approval and publication remain separate governed transitions where configured.</div><div class="imx-form" style="margin-top:12px">'+form.fields.map(function(def){return fieldHtml(def,row);}).join('')+'</div>';openDrawer((row.id?'Edit ':'Create ')+form.title,body,button('Cancel','imv2CloseDrawer()')+button(row.id?'Save changes':'Save draft',"imv2SaveForm('"+kind+"','"+esc(row.id||'')+"')",'primary','ti-device-floppy'));};

function serialise(kind){var form=FORMS[kind],top={},payload={};form.fields.forEach(function(def){var key=def[1],type=def[2],value=val('imx-f-'+key);if(type==='number')value=value===''?null:Number(value);if(['payload','test_cases','decisions'].includes(key)){try{value=value?JSON.parse(value):(key==='payload'?{}:[]);}catch(_){throw new Error(def[0]+' must contain valid JSON');}}if(key==='source_links')value=value?value.split(',').map(function(v){return v.trim();}).filter(Boolean):[];if(['incident_id','investigation_id','title','status','confidentiality','owner_name','due_date','effective_from','effective_to','workspace','code','name','description','scope_type','scope_id','payload','test_cases','change_reason','source_links','version_no','copied_from_id'].includes(key))top[key]=value||null;else payload[key]=value;} );return {top:top,payload:payload};}
async function persist(tableName,body,id){var url='/'+tableName+(id?'?id=eq.'+encodeURIComponent(id):''),options=id?{m:'PATCH',p:'return=representation',b:body}:{m:'POST',p:'return=representation',b:Object.assign({created_by:userId(),created_at:new Date().toISOString()},body)},out=await api(url,options);return out?.[0]||Object.assign({id:id||'local-'+Date.now()},body);}
