window.imv2InvTab=function(tab,btn){enhanceInvestigationTabs();document.querySelectorAll('#ims-inv-form [id^="inv-tab-"]').forEach(function(b){b.classList.remove('active');});var selected=btn||document.getElementById('inv-tab-'+tab);if(selected)selected.classList.add('active');['ws1','ws2','rca','ws3','ca','sign'].forEach(function(name){var el=document.getElementById('inv-'+name);if(el)el.style.display='none';});document.querySelectorAll('.imx-investigation-panel').forEach(function(el){el.classList.remove('active');el.style.display='none';});var legacy={ws1:'ws1',ws2:'ws2',rca:'rca',ca:'ca',sign:'sign'}[tab];if(legacy){var el=document.getElementById('inv-'+legacy);if(el)el.style.display='block';return;}if(tab==='analysis'){var rca=document.getElementById('inv-rca');if(rca)rca.style.display='block';return;}var panel=document.getElementById('inv-imx-'+tab);if(panel){panel.classList.add('active');panel.style.display='block';renderInvPanel(tab);}};
window.imsNewInvestigation=function(linkedEventId){if(legacyInvNew)legacyInvNew(linkedEventId);setTimeout(function(){imv2InvTab('overview',document.getElementById('inv-tab-overview'));},0);};
window.imsOpenInvestigation=function(id){if(legacyInvOpen)legacyInvOpen(id);setTimeout(function(){imv2InvTab('overview',document.getElementById('inv-tab-overview'));},0);};

window.imv2StartTeamReview=function(){var inv=currentInvestigation(),incident=currentInvestigationIncident(inv),existing=invRecords('review',inv,incident).find(function(r){return !['completed','cancelled'].includes(r.status);});if(existing)return imv2OpenForm('review',existing);var summary=['Incident '+(incident.id?incidentRef(incident):'not linked'),incidentTitle(incident),'Actual severity: '+(incident.severity||'not classified'),'Potential severity: '+(incident.potential_severity||'not classified'),'Evidence records: '+(X.data.evidence||[]).filter(function(e){return String(e.event_id)===String(incident.id);}).length,'Causal records: '+invRecords('cause',inv,incident).length,'Open actions: '+(X.data.actions||[]).filter(function(a){return String(a.source_id)===String(inv.id)&&!['closed','completed'].includes(a.status);}).length].join('\n');var decisions=[{agenda:'Confirm facts',decision:'defer',rationale:'Review required',owner:userName(),due_date:''},{agenda:'Resolve gaps and contradictions',decision:'defer',rationale:'Review required',owner:userName(),due_date:''},{agenda:'Validate causes and action coverage',decision:'defer',rationale:'Review required',owner:userName(),due_date:''},{agenda:'Regulatory and learning decision',decision:'defer',rationale:'Review required',owner:userName(),due_date:''}];imv2OpenForm('review',{incident_id:incident.id||'',investigation_id:inv.id||'',title:'Team Review · '+(incident.id?incidentRef(incident):(inv.investigation_ref||'Investigation')),review_type:'analysis_review',meeting_at:new Date().toISOString().slice(0,16),owner_name:userName(),participants:userName()+' · Chair / attendance pending',preread:summary,decisions:JSON.stringify(decisions,null,2),gaps:'Create evidence, interview, analysis or action requests during the review.',status:'draft'});};

